        const host = (prev && prev.closest && prev.closest("[aria-modal='true']")) || modals[modals.length - 1] || document.body;
        host.append(ta);
        try {
            ta.focus({ preventScroll: true });
        }
        catch {
        }
        ta.select();
        let ok = false;
        try {
            ok = document.execCommand("copy");
        }
        catch {
        }
        ta.remove();
        if (prev && prev !== document.body)
            Focus.Set(prev);
