            checkOpts("PageHeader", o);
            const t = this;
            o = o || {};
            const level = Math.max(1, Math.min(6, o.Level || 1));
            const menu = level === 1 && o.MenuTitle !== false && typeof Sw.MenuTitle === "function" ? Sw.MenuTitle() : null;
            t.FromMenu = !!menu;
