        const titleE = el("h" + (o.Level || 1) + ".sw-ph-title", { text: o.Title || "" });
        const descE = el("p.sw-ph-desc", { text: o.Description || "" });
        descE.hidden = !o.Description;
        const statusE = el("div.sw-ph-status");
